from pydantic import ValidationError
from fastapi.sse import ServerSentEvent

@pytest.mark.parametrize("field", ["id", "event"])
def test_sse_field_no_newlines(field):
    try:
        ServerSentEvent(data="test", **{field: "line1\nline2"})
        pytest.fail(f"Should have raised ValueError for field {field}")
    except (ValueError, ValidationError) as e:
        print(f"Caught {type(e)} for {field}: {e}")

